        from collections import defaultdict
        first_token_groups: dict[int, list[str]] = defaultdict(list)

        for role in self.spec.all_roles:
            token_ids = self.spec.role_token_ids[role]
            first_id = token_ids[0]
            self.spec.role_first_token[role] = first_id
            first_token_groups[first_id].append(role)

        collision_groups = {tid: roles for tid, roles in first_token_groups.items() if len(roles) > 1}
        if collision_groups:
            n_colliding = sum(len(v) for v in collision_groups.values())
            logger.warning(
                "Role first-token collisions: %d/%d roles in %d groups.",
                n_colliding, len(self.spec.all_roles), len(collision_groups),
            )
            # Check same-event collisions (the ones that actually matter)
            same_event_problems = []
            for tid, roles in collision_groups.items():
                roles_set = set(roles)
                for evt_type, evt_data in self.spec.argument_constraints.items():
                    evt_roles = set(evt_data.keys())
                    overlap = roles_set & evt_roles
                    if len(overlap) > 1:
                        same_event_problems.append((evt_type, tid, sorted(overlap)))

            if same_event_problems:
                logger.warning(
